import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"Exportación e Importación","description":"","frontmatter":{},"headers":[],"relativePath":"es/advanced/export-import.md","filePath":"es/advanced/export-import.md","lastUpdated":1784904021000}'),n={name:"es/advanced/export-import.md"};function p(r,a,o,l,c,h){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="exportacion-e-importacion" tabindex="-1">Exportación e Importación <a class="header-anchor" href="#exportacion-e-importacion" aria-label="Permalink to &quot;Exportación e Importación&quot;">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripción General <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción General&quot;">​</a></h2><p>swag2mcp admite el ciclo completo del espacio de trabajo mediante archivos ZIP. Puede exportar todo su espacio de trabajo (configuración, archivos de especificación, scripts de autenticación) a un archivo ZIP y restaurarlo en otra máquina.</p><h2 id="exportacion" tabindex="-1">Exportación <a class="header-anchor" href="#exportacion" aria-label="Permalink to &quot;Exportación&quot;">​</a></h2><p>Crea una copia de seguridad ZIP portátil de su espacio de trabajo.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exportar al archivo predeterminado (swag2mcp-backup-&amp;lt;timestamp&amp;gt;.zip)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exportar con ruta personalizada</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups/swag2mcp-backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exportar solo especificaciones específicas</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><h3 id="que-se-incluye-en-la-exportacion" tabindex="-1">Qué se incluye en la exportación <a class="header-anchor" href="#que-se-incluye-en-la-exportacion" aria-label="Permalink to &quot;Qué se incluye en la exportación&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Elemento</th><th>Descripción</th></tr></thead><tbody><tr><td><code>swag2mcp.yaml</code></td><td>Archivo de configuración</td></tr><tr><td><code>specs/</code></td><td>Todos los archivos de especificación (OpenAPI/Swagger/Postman)</td></tr><tr><td><code>auth_scripts/</code></td><td>Scripts de autenticación</td></tr><tr><td><code>swag2mcp.meta</code></td><td>Metadatos (información de versión para compatibilidad)</td></tr></tbody></table><p>La caché y las respuestas <strong>no</strong> se exportan — son transitorias y estarían obsoletas al restaurar.</p><h3 id="nombre-de-archivo-predeterminado" tabindex="-1">Nombre de archivo predeterminado <a class="header-anchor" href="#nombre-de-archivo-predeterminado" aria-label="Permalink to &quot;Nombre de archivo predeterminado&quot;">​</a></h3><p>Si no especifica una ruta de salida, el archivo se guarda como <code>swag2mcp-backup-&lt;YYYY-MM-DD-HHMMSS&gt;.zip</code> en el directorio actual (marca de tiempo UTC).</p><h2 id="importacion" tabindex="-1">Importación <a class="header-anchor" href="#importacion" aria-label="Permalink to &quot;Importación&quot;">​</a></h2><p>Restaura un espacio de trabajo desde una copia de seguridad ZIP o importa archivos de especificación.</p><h3 id="restaurar-desde-zip" tabindex="-1">Restaurar desde ZIP <a class="header-anchor" href="#restaurar-desde-zip" aria-label="Permalink to &quot;Restaurar desde ZIP&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restaurar espacio de trabajo completo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restaurar con sobrescritura</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>El ZIP debe ser creado por <code>swag2mcp export</code> — los archivos ZIP arbitrarios no funcionarán.</p><h3 id="importar-un-solo-archivo-de-especificacion" tabindex="-1">Importar un solo archivo de especificación <a class="header-anchor" href="#importar-un-solo-archivo-de-especificacion" aria-label="Permalink to &quot;Importar un solo archivo de especificación&quot;">​</a></h3><p>Descargue un archivo de especificación y agréguelo al espacio de trabajo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myspec</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myspec</span></span></code></pre></div><h3 id="importacion-masiva-desde-configuracion-existente" tabindex="-1">Importación masiva desde configuración existente <a class="header-anchor" href="#importacion-masiva-desde-configuracion-existente" aria-label="Permalink to &quot;Importación masiva desde configuración existente&quot;">​</a></h3><p>Descargue todos los archivos de especificación de colección para las especificaciones (dominios) indicadas:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><p>Esto descarga el archivo de especificación de cada colección, lo guarda en <code>specs/</code> y actualiza la configuración para que apunte a la copia local.</p><h2 id="casos-de-uso" tabindex="-1">Casos de uso <a class="header-anchor" href="#casos-de-uso" aria-label="Permalink to &quot;Casos de uso&quot;">​</a></h2><h3 id="copia-de-seguridad" tabindex="-1">Copia de seguridad <a class="header-anchor" href="#copia-de-seguridad" aria-label="Permalink to &quot;Copia de seguridad&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y-%m-%d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h3 id="transferencia-a-otra-maquina" tabindex="-1">Transferencia a otra máquina <a class="header-anchor" href="#transferencia-a-otra-maquina" aria-label="Permalink to &quot;Transferencia a otra máquina&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># En la máquina antigua</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copie el ZIP a la máquina nueva, luego:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span></code></pre></div><h3 id="compartir-configuracion" tabindex="-1">Compartir configuración <a class="header-anchor" href="#compartir-configuracion" aria-label="Permalink to &quot;Compartir configuración&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template.zip</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Comparta template.zip con un colega</span></span></code></pre></div><h2 id="verificacion-posterior-a-la-exportacion" tabindex="-1">Verificación posterior a la exportación <a class="header-anchor" href="#verificacion-posterior-a-la-exportacion" aria-label="Permalink to &quot;Verificación posterior a la exportación&quot;">​</a></h2><p>Siempre verifique que el archivo ZIP se haya creado:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-backup-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h2 id="notas-importantes" tabindex="-1">Notas importantes <a class="header-anchor" href="#notas-importantes" aria-label="Permalink to &quot;Notas importantes&quot;">​</a></h2><ul><li><strong>La salida debe ser una ruta de archivo que termine en <code>.zip</code></strong> — no pase un directorio</li><li><strong>La caché y las respuestas están excluidas</strong> — solo se conservan la configuración, las especificaciones y los scripts de autenticación</li><li><strong>El ZIP es autónomo</strong> — puede restaurarse en cualquier máquina con swag2mcp instalado</li><li><strong>Filtro de especificaciones</strong> — use <code>--spec</code> para exportar o importar solo especificaciones específicas</li></ul>`,35)])])}const g=s(n,[["render",p]]);export{k as __pageData,g as default};
